// ── Auth check ──
const auth = $('Auth Lookup').item.json;
if (!auth.home_scope || auth.home_scope === '__UNAUTHORIZED__') {
  return [{ json: { valid: false, error: 'Unauthorized: invalid API key' } }];
}
const homeScope = auth.home_scope;
const allowedScopes = Array.isArray(auth.allowed_scopes) ? auth.allowed_scopes : [];
const readScopes = [homeScope, ...allowedScopes];

const body = $('Extract Key').item.json.body;

const query = body.query;
const category = body.category || null;
const tags = body.tags || null;
let limit = parseInt(body.limit) || 5;
if (limit < 1) limit = 1;
if (limit > 20) limit = 20;

if (!query || typeof query !== 'string' || query.trim() === '') {
  return [{ json: { valid: false, error: 'query is required' } }];
}

return [{ json: { valid: true, query: query.trim(), category, tags, limit, readScopes } }];

const meta = $('Build Query').item.json;
const embeddingResponse = $('Generate Query Embedding').item.json;
const embedding = embeddingResponse.embeddings[0];
const embeddingStr = '[' + embedding.join(',') + ']';

function esc(val) {
  if (val === null || val === undefined) return 'NULL';
  return "'" + String(val).replace(/'/g, "''") + "'";
}

function escArray(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return "'{}'";
  const inner = arr.map(t => '"' + String(t).replace(/"/g, '\\"').replace(/'/g, "''") + '"').join(',');
  return "'{" + inner + "}'";
}

// Scope filter
const readScopes = meta.readScopes || ['private', 'shared'];
const scopeFilter = `scope IN (${readScopes.map(s => esc(s)).join(', ')})`;

const baseConditions = [scopeFilter];
if (meta.category) {
  baseConditions.push(`category = ${esc(meta.category)}`);
}
if (meta.tags && Array.isArray(meta.tags) && meta.tags.length > 0) {
  baseConditions.push(`tags && ${escArray(meta.tags)}`);
}

const baseWhere = ' AND ' + baseConditions.join(' AND ');

const sql = `
WITH vector_results AS (
  SELECT id, category, tags, title, content, metadata, scope, updated_at,
    1 - (embedding <=> '${embeddingStr}'::vector) AS vector_score,
    ts_rank(
      to_tsvector('german', coalesce(title, '') || ' ' || content),
      plainto_tsquery('german', ${esc(meta.query)})
    ) AS text_score
  FROM context_blocks
  WHERE embedding IS NOT NULL${baseWhere}
),
fulltext_results AS (
  SELECT id, category, tags, title, content, metadata, scope, updated_at,
    0.0::float AS vector_score,
    ts_rank(
      to_tsvector('german', coalesce(title, '') || ' ' || content),
      plainto_tsquery('german', ${esc(meta.query)})
    ) AS text_score
  FROM context_blocks
  WHERE embedding IS NULL${baseWhere}
),
combined AS (
  SELECT *,
    (0.7 * vector_score + 0.3 * CASE WHEN text_score > 0 THEN LEAST(text_score * 3, 1.0) ELSE 0 END) AS combined_score
  FROM vector_results
  UNION ALL
  SELECT *,
    (CASE WHEN text_score > 0 THEN LEAST(text_score * 3, 1.0) ELSE 0.01 END) AS combined_score
  FROM fulltext_results
)
SELECT id, category, tags, title, content, metadata, scope, updated_at,
  round(vector_score::numeric, 4) AS vector_score,
  round(text_score::numeric, 4) AS text_score,
  round(combined_score::numeric, 4) AS combined_score
FROM combined
ORDER BY combined_score DESC
LIMIT ${meta.limit}
`;

return [{ json: { sql, query: meta.query, limit: meta.limit } }];

const results = $input.all().filter(item => item.json && item.json.id);
const originalQuery = $('Build Hybrid SQL').item.json.query;

if (results.length === 0) {
  return [{ json: {
    skipLLM: true,
    answer: 'Keine relevanten Ergebnisse gefunden für: ' + originalQuery,
    sources: []
  } }];
}

// Truncate large blocks to prevent one source dominating
const MAX_BLOCK_CHARS = 1500;
const contextBlocks = results.map((item, i) => {
  const r = item.json;
  let content = r.content;
  if (content.length > MAX_BLOCK_CHARS) {
    content = content.substring(0, MAX_BLOCK_CHARS) + '\n[... truncated]';
  }
  return `[${i+1}] "${r.title}" (${r.category}, score: ${r.combined_score}):\n${content}`;
}).join('\n\n---\n\n');

const sources = results.map(item => ({
  id: item.json.id,
  title: item.json.title,
  category: item.json.category,
  score: String(item.json.combined_score)
}));

const systemPrompt = `<role>You are a RAG (Retrieval-Augmented Generation) assistant.</role>

<task>Answer the user's question using ONLY the provided context blocks.</task>

<constraints>
1. Maximum response length: 150 words. Be as concise as possible.
2. Cite sources using [1], [2], [3] notation matching the context block numbers.
3. Use ONLY facts from the context blocks. Zero external knowledge.
4. If the context blocks do not contain the answer, respond exactly: "Die verfügbaren Quellen enthalten keine Antwort auf diese Frage."
5. Zero tolerance for hallucination. Never invent facts.
6. Answer in the same language as the user's question.
7. Do NOT summarize the entire context. Extract only what answers the question.
</constraints>`;

const userPrompt = `QUESTION: ${originalQuery}

CONTEXT BLOCKS (search these for the answer):
${contextBlocks}

Answer the QUESTION above based on the context blocks. Focus on the specific question. Be concise.`;

const ollamaBody = JSON.stringify({
  model: $vars.OLLAMA_CHAT_MODEL,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  stream: false,
  options: { temperature: 0, num_predict: 1500 }
});

return [{ json: {
  skipLLM: false,
  ollamaBody,
  sources,
  resultCount: results.length
} }];

const prepData = $('Prepare LLM Prompt').item.json;
const llmResponse = $('LLM Synthesis').item.json;
const answer = llmResponse.message ? llmResponse.message.content : 'No response from LLM';

return [{ json: {
  success: true,
  answer: answer,
  sources: prepData.sources,
  model: llmResponse.model || $vars.OLLAMA_CHAT_MODEL,
  eval_count: llmResponse.eval_count || null
} }];

const prepData = $('Prepare LLM Prompt').item.json;
return [{ json: {
  success: true,
  answer: prepData.answer,
  sources: []
} }];

